/// <summary>
///     AVA <c>avaResponsibleFieldWorkerResponsibilityId</c> method.
///     AVA - Schneider 28.05.2024
/// </summary>
/// <returns>
///     <c>smmResponsibilityId</c> as return value
/// </returns>
public static smmResponsibilityId avaResponsibleFieldWorkerResponsibilityId()
{
    smmResponsibilityId retVal;

    #define.ADM('ADM')

    retVal = #ADM;

    if(smmResponsibilityGroup::find(retVal).RecId == 0)
    {
        retVal = ''; 
    }

    return retVal;
}
